Q: Talking to a Web API from a Webforms application A: <p>You can use the   <code>Microsoft.AspNet.WebApi.Client</code> to use your restful API.
Here is an official example from the asp.net site:</p>
<p><a href="https://learn.microsoft.com/en-us/aspnet/web-api/overview/advanced/calling-a-web-api-from-a-net-client" rel="nofollow noreferrer">https://learn.microsoft.com/en-us/aspnet/web-api/overview/advanced/calling-a-web-api-from-a-net-client</a></p>
<pre><code>using System;
using System.Net;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Threading.Tasks;

namespace HttpClientSample
{
    public class Product
    {
        public string Id { get; set; }
        public string Name { get; set; }
        public decimal Price { get; set; }
        public string Category { get; set; }
    }

    class Program
    {
        static HttpClient client = new HttpClient();

        static void ShowProduct(Product product)
        {
            Console.WriteLine($&quot;Name: {product.Name}\tPrice: &quot; +
                $&quot;{product.Price}\tCategory: {product.Category}&quot;);
        }

        static async Task&lt;Uri&gt; CreateProductAsync(Product product)
        {
            HttpResponseMessage response = await client.PostAsJsonAsync(
                &quot;api/products&quot;, product);
            response.EnsureSuccessStatusCode();

            // return URI of the created resource.
            return response.Headers.Location;
        }

        static async Task&lt;Product&gt; GetProductAsync(string path)
        {
            Product product = null;
            HttpResponseMessage response = await client.GetAsync(path);
            if (response.IsSuccessStatusCode)
            {
                product = await response.Content.ReadAsAsync&lt;Product&gt;();
            }
            return product;
        }

        static async Task&lt;Product&gt; UpdateProductAsync(Product product)
        {
            HttpResponseMessage response = await client.PutAsJsonAsync(
                $&quot;api/products/{product.Id}&quot;, product);
            response.EnsureSuccessStatusCode();

            // Deserialize the updated product from the response body.
            product = await response.Content.ReadAsAsync&lt;Product&gt;();
            return product;
        }

        static async Task&lt;HttpStatusCode&gt; DeleteProductAsync(string id)
        {
            HttpResponseMessage response = await client.DeleteAsync(
                $&quot;api/products/{id}&quot;);
            return response.StatusCode;
        }

        static void Main()
        {
            RunAsync().GetAwaiter().GetResult();
        }

        static async Task RunAsync()
        {
            // Update port # in the following line.
            client.BaseAddress = new Uri(&quot;http://localhost:64195/&quot;);
            client.DefaultRequestHeaders.Accept.Clear();
            client.DefaultRequestHeaders.Accept.Add(
                new MediaTypeWithQualityHeaderValue(&quot;application/json&quot;));

            try
            {
                // Create a new product
                Product product = new Product
                {
                    Name = &quot;Gizmo&quot;,
                    Price = 100,
                    Category = &quot;Widgets&quot;
                };

                var url = await CreateProductAsync(product);
                Console.WriteLine($&quot;Created at {url}&quot;);

                // Get the product
                product = await GetProductAsync(url.PathAndQuery);
                ShowProduct(product);

                // Update the product
                Console.WriteLine(&quot;Updating price...&quot;);
                product.Price = 80;
                await UpdateProductAsync(product);

                // Get the updated product
                product = await GetProductAsync(url.PathAndQuery);
                ShowProduct(product);

                // Delete the product
                var statusCode = await DeleteProductAsync(product.Id);
                Console.WriteLine($&quot;Deleted (HTTP Status = {(int)statusCode})&quot;);

            }
            catch (Exception e)
            {
                Console.WriteLine(e.Message);
            }

            Console.ReadLine();
        }
    }
}
</code></pre>
<p>If you need call your custom function <code>MyProcessFunction</code> first you need to define the function in the controller</p>
<pre><code> public IEnumerable&lt;string&gt; MyProcessFunctionName()
 {
 return new string[] { &quot;value1&quot;, &quot;value2&quot; };
 }
</code></pre>
<p>after that, if you need to call it by name <code>client.GetAsync(&quot;api/products/MyProcessFunctionName&quot;)</code> you need to <a href="https://stackoverflow.com/questions/9569270/custom-method-names-in-asp-net-web-api">change the RouteConfig file to allow API calls by action name</a>:</p>
<pre><code>Routes.MapHttpRoute(
    name: &quot;DefaultApi&quot;,
    routeTemplate: &quot;api/{controller}/{action}/{id}&quot;,
    defaults: new { action = &quot;get&quot;, id = RouteParameter.Optional }
);
</code></pre>
